	defer cancel()
	parentDeadline, _ := parentCtx.Deadline()

	var gotDeadline time.Time
	generateTranscriptSummary = func(
		ctx context.Context,
		_ redact.RedactedBytes,
		_ []string,
		_ types.AgentType,
